    (hfirst : EmitSpec first input startWork middleWork
      startOutput middleOutput firstTime)
    (hsecond : EmitSpec second input middleWork endWork
      middleOutput endOutput secondTime) :
    EmitSpec (seqTM first second) input startWork endWork
      startOutput endOutput (firstTime + 1 + secondTime)

theorem choiceStream_of_loaded {Q : Type} {c : Cfg (k + 1) Q} {g : ℕ → Bool} {T : ℕ}
    (h : ∀ j < T, (c.work (Fin.last k)).cells ((c.work (Fin.last k)).head + j) = Γ.ofBool (g j))
    {j : ℕ} (hj : j < T) : choiceStream c j = g j

theorem step_ofGuess (M : TM (k + 1)) (hM : TM.GuessDiscipline M) {c : Cfg (k + 1) M.Q}
    (hb : ∃ b : Bool, (c.work (Fin.last k)).read = Γ.ofBool b) :
    (choiceTM (ofGuess M)).step c = M.step c

theorem dropChoice_stepCfg (M : TM (k + 1)) {c : Cfg (k + 1) M.Q} {b : Bool}
    (hread : (c.work (Fin.last k)).read = Γ.ofBool b) :
