theorem traceD_succ_back (M : TM n) : ∀ (T : ℕ) (c : Cfg n M.Q),
    M.traceD (T + 1) c =
      if (M.traceD T c).state = M.qhalt then M.traceD T c else M.stepCfg (M.traceD T c)

