theorem scratch_idem {work₀ : Fin n → Tape} {tmp tmp2 : Fin n}
    (htt2 : tmp ≠ tmp2) (z z' : ℕ) :
    scratch (scratch work₀ tmp tmp2 z) tmp tmp2 z' = scratch work₀ tmp tmp2 z'

