    (mkPos mkNeg : ℕ → LitDesc n) (f : ℕ → ℕ) {qs : List ℕ}
    (hpos : ∀ q ∈ qs, R (mkPos q) ⟨true, f q⟩)
    (hneg : ∀ q ∈ qs, R (mkNeg q) ⟨false, f q⟩) :
